import{_ as e,o as a,c as o,ag as i}from"./chunks/framework.DC2anBTf.js";const g=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/introduction.md","filePath":"en/guide/introduction.md","lastUpdated":1793538094000}'),r={name:"en/guide/introduction.md"};function s(n,t,d,l,c,u){return a(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><h2 id="why-this-architecture-exists" tabindex="-1">Why This Architecture Exists <a class="header-anchor" href="#why-this-architecture-exists" aria-label="Permalink to &quot;Why This Architecture Exists&quot;">​</a></h2><p>uni-app x is DCloud&#39;s next-generation cross-platform solution: the UTS language with a compile-time static model, one codebase compiling to JS (Web / mini-programs) and native Kotlin / Swift. The performance is excellent — but when you set out to build a serious mid-to-large project, you hit a reality: <strong>the default ecosystem shape is a &quot;pile of pages&quot;</strong>. Requests are written inside pages, state hangs off page data, navigation relies on bare string paths, and responses are raw <code>UTSJSONObject</code> subscript access.</p><p>The engineering tooling from the standard Vue3 ecosystem (vue-router&#39;s single route table, pinia&#39;s plugin protocol, axios wrappers, synchronous js-cookie reads) <strong>cannot be transplanted directly</strong>. uni-app x pages follow a compile-time static model with four fundamental differences:</p><ol><li><strong>No single route table</strong> — pages are statically registered in <code>pages.json</code>, fixed at compile time;</li><li><strong>Plugin protocol unreliable</strong> — <code>app.use(pinia)</code> on the App side (Kotlin) is verified not to work;</li><li><strong>Storage is entirely async</strong> — no synchronous cookie available;</li><li><strong>Nominal type system</strong> — incompatible types on the Kotlin side are not errors but cast crashes.</li></ol><p>This means the engineering layering must be <strong>redesigned</strong> under platform constraints. This template is the complete implementation of that design.</p><h2 id="design-goals" tabindex="-1">Design Goals <a class="header-anchor" href="#design-goals" aria-label="Permalink to &quot;Design Goals&quot;">​</a></h2><ul><li><strong>Complete layering</strong>: api / stores / router / utils / pages each with a single responsibility, clear type contracts, one assembly point;</li><li><strong>Auth out of the box</strong>: login loop, global guards, and cold-start race elimination all built in;</li><li><strong>Reproducible</strong>: every architectural decision has explicit criteria and verified evidence; integrating a real backend requires changing exactly one configuration point.</li></ul><h2 id="tech-stack" tabindex="-1">Tech Stack <a class="header-anchor" href="#tech-stack" aria-label="Permalink to &quot;Tech Stack&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Description</th></tr></thead><tbody><tr><td>Framework</td><td>uni-app x (HBuilderX 5.34+, VDOM mode, vapor: true)</td></tr><tr><td>Language</td><td>UTS (compiles to JS / Kotlin / Swift)</td></tr><tr><td>UI paradigm</td><td>Vue3 Composition API, uvue pages</td></tr><tr><td>State management</td><td>ux-pinia (class-style stores, mount-free)</td></tr><tr><td>Routing</td><td>ux-router (vue-router-style API + global guards)</td></tr><tr><td>Networking</td><td>mx-request (interceptor system)</td></tr><tr><td>Persistence</td><td>ux-storage (async)</td></tr><tr><td>Feedback</td><td>ux-utils (toast / modal, self-drawn on all platforms)</td></tr><tr><td>UI components</td><td>m-ui-x (11 base components, zero-registration easycom)</td></tr></tbody></table><h2 id="layers-and-plugin-mapping" tabindex="-1">Layers and Plugin Mapping <a class="header-anchor" href="#layers-and-plugin-mapping" aria-label="Permalink to &quot;Layers and Plugin Mapping&quot;">​</a></h2><p>Each layer has a single responsibility with one-way dependencies:</p><table tabindex="0"><thead><tr><th>Layer</th><th>Location</th><th>Plugin</th></tr></thead><tbody><tr><td>Network (global config + dual interceptors)</td><td><code>utils/request.uts</code></td><td>mx-request</td></tr><tr><td>API (domain functions + DTO restoration)</td><td><code>api/*.uts</code></td><td>mx-request</td></tr><tr><td>Credentials (synchronous token reads)</td><td><code>utils/auth.uts</code></td><td>ux-storage</td></tr><tr><td>State (business state and actions)</td><td><code>stores/modules/*.uts</code></td><td>ux-pinia</td></tr><tr><td>Routing (named routes + guard chain)</td><td><code>router/index.uts</code></td><td>ux-router</td></tr><tr><td>Global guard (auth redirects)</td><td><code>router/permission.uts</code></td><td>ux-router guard</td></tr><tr><td>Config (single source of global config)</td><td><code>config/index.uts</code></td><td>—</td></tr><tr><td>View (statically registered pages)</td><td><code>pages/</code></td><td>uni-app x convention</td></tr></tbody></table><p>Two platform facts worth knowing:</p><ul><li>uni-app x has no global layout mechanism; each page owns its own structure;</li><li>The old notion of <code>computed</code> acting as getters in setup-style stores is outdated — ux-pinia 0.2.0 uses class-style stores, with derived values expressed as class getters.</li></ul><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="./getting-started.html">Quick Start</a>: clone, configure, run;</li><li><a href="./architecture.html">Architecture</a>: directory structure, call chain, and assembly paradigm;</li><li><a href="./conventions.html">Conventions</a>: type organization, UTS red lines, and domain-specific rules.</li></ul>',17)])])}const h=e(r,[["render",s]]);export{g as __pageData,h as default};
